using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchExportIndexFileStore{private readonly string _path;public AndroidResearchExportIndexFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidResearchExportIndex value){if(string.IsNullOrWhiteSpace(value.Fingerprint))throw new InvalidOperationException("Research export index fingerprint is required.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidResearchExportIndex Load()=>JsonSerializer.Deserialize<AndroidResearchExportIndex>(File.ReadAllText(_path))??throw new InvalidOperationException("Research export index JSON is invalid.");}
